  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "The closest analogue (GNE-7915, Morgan 0.797) achieved a CSF/unbound plasma AUC ratio of 0.8 in NHPs, directly demonstrating high CNS penetration; the query shares the identical aniline-morpholine amide, fluoro, methoxy, and CF3-pyrimidine core, differing only in the 6-amino substituent (ethyl vs cyclopropyl).",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "In NHPs, GNE-7915 had an unbound brain/unbound plasma ratio of 0.69, confirming meaningful brain tissue exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "In rats, GNE-7915 showed a CSF/plasma unbound ratio of 0.6 after IV dosing, providing cross-species evidence of brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "In mice, GNE-7915 reached 500 ng/g brain tissue, demonstrating effective CNS delivery.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "A close analogue with methylamino and chloro substitution instead of ethylamino/fluoro had a poor Bu/Pu of 0.11, showing that small changes in this series can impair CNS exposure; however the query retains the fluoro and cyclopropyl features closer to the brain-penetrant GNE-7915.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a close analogue of the well-characterized brain-penetrant GNE-7915, sharing the same core and differing only by a cyclopropyl-for-ethyl amino substituent. Multiple direct in vivo measurements in mouse, rat, and NHP show high unbound brain and CSF exposure for GNE-7915, and the cyclopropyl change is expected to preserve or improve passive permeability. A less similar methylamino/chloro analogue with poor Bu/Pu is outweighed by the higher-similarity, multi-species positive data. Prediction: pass.",
  "evidence_gaps": [
    "No direct experimental measurement for the exact query; the closest data are for the ethylamino analogue.",
    "The effect of replacing ethyl with cyclopropyl on transporter-mediated efflux is not directly measured.",
    "No human CNS exposure data for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

